for i, owner in enumerate(owners, 1):
    try:
        resp = requests.post('http://localhost:8000/api/owners/', json=owner, headers=headers)
        if resp.status_code == 201:
            data = resp.json()
            name = data.get('company_name') or (data.get('first_name', '') + ' ' + data.get('last_name', ''))
            print('OK ' + str(i) + '/50 - ' + data['reference'] + ' - ' + name.strip())
            success += 1
        else:
            print('FAIL ' + str(i) + ' - ' + resp.text[:100])
    except Exception as e:
        print('ERR ' + str(i) + ' - ' + str(e))

